CREATE PROCEDURE [tarel_demo].[usp_StageInternetSales]
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO [tarel_demo].[InternetSalesStage]
    SELECT sales.[SalesOrderNumber], sales.[OrderDateKey], sales.[ProductKey], sales.[SalesAmount]
    FROM [dbo].[FactInternetSales] AS sales
    INNER JOIN [dbo].[DimDate] AS dates
        ON dates.[DateKey] = sales.[OrderDateKey];
END;
